create table xxventuri.xxeba_customer_complaints_t (
    complaint_id       varchar2(20 byte),
    complaint_number   number,
    account_id         number,
    raised_date        date,
    raised_by          varchar2(50 byte),
    contact_number     varchar2(100 byte),
    raised_source      varchar2(20 byte),
    complaint_type     varchar2(30 byte),
    complaint_products varchar2(1000 byte),
    complaint_subject  varchar2(1000 byte),
    complaint_desc     varchar2(1000 byte),
    assigned_to        number,
    root_cause         varchar2(200 byte),
    corrective_action  varchar2(200 byte),
    preventive_action  varchar2(200 byte),
    resolved_remarks   varchar2(200 byte),
    resolved_by        number,
    resolved_date      date,
    verified_remarks   varchar2(200 byte),
    verified_by        varchar2(100 byte),
    verified_date      date,
    status             varchar2(10 byte),
    created            timestamp(6),
    created_by         varchar2(50 byte),
    updated            timestamp(6),
    updated_by         varchar2(50 byte)
);

alter table xxventuri.xxeba_customer_complaints_t
    add constraint complaint_id_pk primary key ( complaint_id )
        using index enable;


